"""Credit memo, sanction letter (with KFS-style summary) and rejection letter — markdown.

All content is generated from the :class:`~app.schemas.CaseDetail`; nothing is invented.
PII: only masked PAN / Aadhaar are ever rendered.
"""
from __future__ import annotations

from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any

import yaml

from app.schemas import CaseDetail, DecisionOutcome, RuleHit, RuleOutcome

_POLICY_FILE = Path(__file__).resolve().parents[1] / "policy" / "policy_v1.yaml"

DISCLAIMER = (
    "_Decision support generated by FinPilot HomeLoan. This memo is a draft for the credit "
    "underwriter; final credit decisions follow the lender's board-approved credit policy and "
    "applicable RBI/NHB regulations. Synthetic data — illustrative policy, not Hero Housing "
    "Finance's actual policy._"
)

APPROVED = (DecisionOutcome.APPROVE, DecisionOutcome.APPROVE_WITH_CONDITIONS)


# --------------------------------------------------------------------------- helpers
def policy_raw() -> dict[str, Any]:
    try:
        from app.policy.loader import get_policy
        return dict(get_policy().raw)
    except ImportError:  # pragma: no cover - loader always present in prod
        with open(_POLICY_FILE, encoding="utf-8") as fh:
            return dict(yaml.safe_load(fh))


def policy_ref(key: str | None) -> str:
    if not key:
        return ""
    return str(policy_raw().get("references", {}).get(key, key))


def emi(principal: float, annual_rate: float, months: int) -> float:
    try:
        from app.engine.finance import emi as _emi
        return float(_emi(principal, annual_rate, months))
    except ImportError:  # pragma: no cover
        if months <= 0:
            return 0.0
        r = annual_rate / 12
        if r == 0:
            return principal / months
        return principal * r * (1 + r) ** months / ((1 + r) ** months - 1)


def inr(x: float | int | None, short: bool = False) -> str:
    if x is None:
        return "—"
    v = float(x)
    if short:
        if abs(v) >= 1e7:
            return f"₹{v / 1e7:.2f} Cr"
        if abs(v) >= 1e5:
            return f"₹{v / 1e5:.2f} L"
    neg = v < 0
    s = f"{abs(round(v)):d}"
    if len(s) > 3:  # Indian digit grouping 12,34,567
        head, tail = s[:-3], s[-3:]
        groups: list[str] = []
        while len(head) > 2:
            groups.insert(0, head[-2:])
            head = head[:-2]
        if head:
            groups.insert(0, head)
        s = ",".join(groups) + "," + tail
    return ("-₹" if neg else "₹") + s


def pct(x: float | None, nd: int = 1) -> str:
    return "—" if x is None else f"{x * 100:.{nd}f}%"


def _md(s: Any) -> str:
    return str(s).replace("|", "\\|").replace("\n", " ")


def apr_approx(principal: float, annual_rate: float, months: int, fee: float) -> float:
    """Annualised all-in cost (nominal APR): IRR of (principal - fee) vs. EMI stream, × 12."""
    if principal <= 0 or months <= 0:
        return 0.0
    pay = emi(principal, annual_rate, months)
    net = principal - fee
    lo, hi = 0.0, 1.0
    for _ in range(200):
        mid = (lo + hi) / 2
        pv = pay * months if mid == 0 else pay * (1 - (1 + mid) ** -months) / mid
        if pv > net:
            lo = mid
        else:
            hi = mid
    return (lo + hi) / 2 * 12


def _rule_table(hits: list[RuleHit]) -> list[str]:
    rows = ["| Rule | Name | Outcome | Effect | Detail | Reference |", "|---|---|---|---|---|---|"]
    order = {RuleOutcome.FAIL: 0, RuleOutcome.WARN: 1, RuleOutcome.INFO: 2, RuleOutcome.PASS: 3}
    for h in sorted(hits, key=lambda r: (order.get(r.outcome, 9), r.rule_id)):
        ref = h.reference or ""
        rows.append(f"| `{h.rule_id}` | {_md(h.name)} | {h.outcome.value} | {h.effect} | "
                    f"{_md(h.detail)} | {_md(ref)[:120]} |")
    return rows


def _fee_pct() -> float:
    return float(policy_raw().get("pricing", {}).get("processing_fee_pct", 0.005))


def _validity_days() -> int:
    return int(policy_raw().get("decision", {}).get("sanction_validity_days", 90))


# --------------------------------------------------------------------------- credit memo
def credit_memo(case: CaseDetail) -> str:
    f, a, b, e, r, c, d = (case.form, case.applicant, case.bank, case.eligibility, case.risk,
                           case.capacity, case.decision)
    lines: list[str] = []
    lines += [f"# Credit Memo — {case.id}", "",
          f"**Product:** {f.product.value.replace('_', ' ')} · **Policy:** {d.policy_version or e.policy_version}"
          f" · **Prepared:** {case.created_at:%d %b %Y %H:%M} UTC · **Status:** {case.status.value}", "",
          f"> **Decision: {d.outcome.value.replace('_', ' ')}**"
          + (f" (engine: {d.engine_outcome.value})" if d.engine_outcome != d.outcome else "")
          + f" — decided by {d.decided_by}", ""]

    lines += ["## 1. Applicant", "", "| Field | Value |", "|---|---|",
          f"| Name | {_md(a.name)} |", f"| Age | {a.age:.1f} yrs |" if a.age else "| Age | — |",
          f"| Employment | {a.employment_type.value.replace('_', ' ').title()} — {_md(a.employer_or_business or '—')} |",
          f"| Years in job / business | {f.years_in_job:g} |",
          f"| PAN (masked) | {a.pan_masked or '—'} |", f"| Aadhaar (masked) | {a.aadhaar_masked or '—'} |",
          f"| City | {a.city or '—'} |", f"| Bureau score | {f.bureau_score or '—'} |"]
    if f.co_applicant:
        ca = f.co_applicant
        lines.append(f"| Co-applicant | {_md(ca.name)} ({ca.relation}), net income {inr(ca.monthly_net_income)}/m |")
    lines.append("")

    lines += ["## 2. Loan request", "", "| Item | Value |", "|---|---|",
          f"| Amount requested | {inr(f.loan_amount)} |", f"| Tenure requested | {f.tenure_months} months |",
          f"| Property value | {inr(f.property_value)} ({f.property_type.lower()}, {f.property_city or '—'}) |",
          f"| Purpose | {_md(f.purpose)} |", f"| Rate type | {f.rate_type.title()} |"]
    if f.lap_end_use:
        lines.append(f"| LAP end use | {_md(f.lap_end_use)} |")
    lines.append("")

    lines += ["## 3. Documents verified", "", "| Document | Type | Read via | Confidence | Flags |",
          "|---|---|---|---|---|"]
    for doc in case.bundle.documents:
        flags = ", ".join(fl.code for fl in doc.flags) or "—"
        lines.append(f"| {_md(doc.filename)} | {doc.doc_type.value} | {doc.ocr_engine} | "
                 f"{doc.classification_confidence:.0%} | {flags} |")
    if case.bundle.missing_documents:
        lines.append("")
        lines.append("**Missing documents:** " + ", ".join(m.value for m in case.bundle.missing_documents))
    if case.bundle.cross_checks:
        lines += ["", "**Cross-checks**", "", "| Field | Match | Score | Note |", "|---|---|---|---|"]
        for cc in case.bundle.cross_checks:
            lines.append(f"| {cc.field} | {'✅' if cc.match else '❌'} | {cc.score:.2f} | {_md(cc.note)} |")
    if case.bundle.flags:
        lines += ["", "**Document / forgery flags**", ""]
        lines += [f"- **{fl.code}** ({fl.severity.value}): {fl.detail}" for fl in case.bundle.flags]
    lines.append("")

    lines += ["## 4. Income assessment", "",
          f"- Declared monthly income: {inr(f.declared_monthly_income)}",
          f"- Bank-evidenced income estimate: {inr(b.income_estimate)} (avg salary credit {inr(b.avg_salary_credit)})"]
    if case.bundle.salary_slips:
        nets = [float(s.get("net", 0) or 0) for s in case.bundle.salary_slips]
        lines.append(f"- Salary slips: {len(nets)} — average net pay {inr(sum(nets) / max(len(nets), 1))}")
    if case.bundle.income_docs:
        ann = case.bundle.income_docs.get("annual_income")
        if ann:
            lines.append(f"- Form 16 / ITR annual income: {inr(float(ann))}")
    lines += [f"- **Income used for FOIR: {inr(e.assessed_income)} / month** — basis: {e.income_basis}",
          f"- Existing obligations: {inr(e.existing_obligations)} / month", ""]

    lines += ["## 5. Bank statement analytics", "", "| Metric | Value |", "|---|---|",
          f"| Months covered | {b.months_covered:g} |",
          f"| Avg monthly balance | {inr(b.avg_monthly_balance)} |", f"| Minimum balance | {inr(b.min_balance)} |",
          f"| Avg monthly credits / debits | {inr(b.avg_monthly_credits)} / {inr(b.avg_monthly_debits)} |",
          f"| Salary regularity | {pct(b.salary_regularity, 0)} |",
          f"| Detected EMIs | {len(b.detected_emis)} totalling {inr(b.total_detected_emi)}/m |",
          f"| Bounces | {b.bounces} |", f"| Cash-deposit spikes | {len(b.cash_deposit_spikes)} |",
          f"| High-risk merchant debits | {len(b.high_risk_merchants)} |", ""]
    lines += [f"- {n}" for n in b.notes]
    if b.notes:
        lines.append("")

    lines += ["## 6. Eligibility", "", "| Parameter | Actual | Policy limit | Status |", "|---|---|---|---|",
          f"| FOIR | {pct(e.foir_actual)} | {pct(e.foir_cap, 0)} | {'✅' if e.foir_actual <= e.foir_cap else '❌'} |",
          f"| LTV (`{e.ltv_rule_id}`) | {pct(e.ltv_actual)} | {pct(e.ltv_cap, 0)} | "
          f"{'✅' if e.ltv_actual <= e.ltv_cap + 1e-9 else '❌'} |",
          f"| Tenure | {f.tenure_months} m | {e.max_tenure_months} m | "
          f"{'✅' if f.tenure_months <= e.max_tenure_months else '❌'} |",
          f"| Age at maturity | {e.age_at_maturity:.1f} | — | — |",
          f"| EMI on request | {inr(e.requested_emi)} | {inr(e.max_emi_affordable)} affordable | "
          f"{'✅' if e.requested_emi <= e.max_emi_affordable else '❌'} |",
          f"| Max loan by FOIR / LTV | {inr(e.max_loan_by_foir)} / {inr(e.max_loan_by_ltv)} | — | — |",
          f"| **Max eligible loan** | **{inr(e.max_eligible_loan)}** | requested {inr(e.requested_amount)} | "
          f"{'✅' if e.eligible else '❌'} |", "",
          f"Rate applied: {pct(e.rate, 2)} p.a."]
    if e.tenure_options:
        lines += ["", "| Tenure option | Max loan | EMI for requested | FOIR at requested |", "|---|---|---|---|"]
        lines += [f"| {t.tenure_months} m | {inr(t.max_loan)} | {inr(t.emi_for_requested)} | {pct(t.foir_at_requested)} |"
              for t in e.tenure_options]
    lines += [f"- {n}" for n in e.notes]
    lines.append("")

    lines += ["## 7. Risk model & explanation", "",
          f"PD **{pct(r.pd, 2)}** · score **{r.score}** · grade **{r.grade}** ({r.band}) · model `{r.model_version}`", "",
          "| Driver | Value | SHAP impact | Explanation |", "|---|---|---|---|"]
    lines += [f"| {_md(s.label)} | {_md(s.value)} | {s.impact:+.3f} | {_md(s.text)} |" for s in r.reasons]
    lines += ["", "_Positive SHAP impact increases estimated default risk._", ""]

    lines += ["## 8. Repayment capacity (Monte Carlo)", "",
          f"- Financial health score: **{c.health_score:.0f}/100**",
          f"- Monthly surplus after proposed EMI: {inr(c.monthly_surplus_after_emi)}",
          f"- Probability of cash shortfall: **{pct(c.prob_shortfall)}** ({c.iterations} simulations)",
          f"- Stress EMI coverage (+200 bps, −15% income): {c.stress_emi_coverage:.2f}x"]
    if c.sub_scores:
        lines += ["", "| Pillar | Score | Weight | Detail |", "|---|---|---|---|"]
        lines += [f"| {s.name} | {s.score:.0f} | {s.weight:.0%} | {_md(s.detail)} |" for s in c.sub_scores]
    if c.basis:
        lines += ["", f"_{c.basis}_"]
    lines.append("")

    fired = [h for h in d.rules_fired if h.outcome != RuleOutcome.PASS]
    passed = [h for h in d.rules_fired if h.outcome == RuleOutcome.PASS]
    lines += ["## 9. Rules fired", ""]
    lines += _rule_table(fired) if fired else ["No exceptions — all rules passed."]
    if passed:
        lines += ["", f"Passed ({len(passed)}): " + ", ".join(f"`{h.rule_id}`" for h in passed)]
    lines.append("")

    lines += ["## 10. Decision", "", "| Item | Value |", "|---|---|",
          f"| Outcome | **{d.outcome.value}** |", f"| Engine outcome | {d.engine_outcome.value} |",
          f"| ML-only suggestion | {d.model_suggested.value} |",
          f"| Sanctioned amount | {inr(d.sanctioned_amount)} |", f"| Tenure | {d.tenure_months} months |",
          f"| Rate | {pct(d.rate, 2)} p.a. ({f.rate_type.lower()}) |", f"| EMI | {inr(d.emi)} |",
          f"| Turnaround | {d.turnaround_ms / 1000:.1f} s |", "", "**Key reasons**", ""]
    lines += [f"{i}. {x}" for i, x in enumerate(d.reasons, 1)] or ["—"]
    lines.append("")

    lines += ["## 11. Conditions", ""]
    lines += [f"- **{cd.code}** — {cd.text}" for cd in d.conditions] or ["None."]
    lines.append("")

    lines += ["## 12. Deviations & overrides", ""]
    if case.overrides:
        lines += ["| When | Underwriter | From | To | Amount | Reason |", "|---|---|---|---|---|---|"]
        lines += [f"| {o.at:%d %b %Y %H:%M} | {_md(o.underwriter)} | {o.from_outcome.value} | {o.to_outcome.value} | "
              f"{inr(o.sanctioned_amount) if o.sanctioned_amount else '—'} | {_md(o.reason)} |" for o in case.overrides]
    else:
        lines.append("No deviations or overrides recorded.")
    lines += ["", "---", "", DISCLAIMER, ""]
    return "\n".join(lines)


# --------------------------------------------------------------------------- letters
def kfs(case: CaseDetail) -> dict[str, Any]:
    """Key Facts Statement-style numbers for a sanction (RBI KFS circular, Apr-2024)."""
    d, f = case.decision, case.form
    amount = d.sanctioned_amount or 0.0
    months = d.tenure_months or f.tenure_months
    rate = d.rate or case.eligibility.rate
    fee = round(amount * _fee_pct(), 0)
    pay = d.emi or emi(amount, rate, months)
    return {
        "sanctioned_amount": amount, "rate_type": f.rate_type, "rate": rate, "tenure_months": months,
        "emi": round(pay, 0), "processing_fee": fee, "apr": apr_approx(amount, rate, months, fee),
        "total_interest": round(pay * months - amount, 0), "total_payable": round(pay * months + fee, 0),
        "validity_days": _validity_days(),
    }


def sanction_letter(case: CaseDetail) -> str:
    d, f, a = case.decision, case.form, case.applicant
    k = kfs(case)
    valid_until = datetime.now(timezone.utc) + timedelta(days=k["validity_days"])
    prod = "Home Loan" if f.product.value == "HOME_LOAN" else "Loan Against Property"
    lines = [f"# Sanction Letter (Draft) — {prod}", "",
         f"**Ref:** {case.id}/SL · **Date:** {datetime.now(timezone.utc):%d %b %Y}", "",
         f"Dear {a.name},", "",
         f"We are pleased to inform you that, subject to the terms below, your application for a {prod} "
         f"has been **sanctioned in principle** for **{inr(k['sanctioned_amount'])}**.", "",
         "## Key Facts Statement (summary)", "", "| Item | Detail |", "|---|---|",
         f"| Loan amount sanctioned | {inr(k['sanctioned_amount'])} |",
         f"| Interest rate type | {k['rate_type'].title()}"
         + (" (repo-linked; resets per RBI floating-rate reset directions)" if k["rate_type"] == "FLOATING" else "")
         + " |",
         f"| Rate of interest (ROI) | {pct(k['rate'], 2)} p.a. |",
         f"| Tenure | {k['tenure_months']} months |", f"| EMI | {inr(k['emi'])} |",
         f"| Processing fee | {inr(k['processing_fee'])} ({pct(_fee_pct(), 2)} of loan) |",
         f"| Annual Percentage Rate (APR, approx.) | {pct(k['apr'], 2)} |",
         f"| Total interest payable (approx.) | {inr(k['total_interest'])} |",
         f"| Total amount payable incl. fee (approx.) | {inr(k['total_payable'])} |",
         "| Prepayment / foreclosure charges | Nil for floating-rate loans to individuals (non-business purpose) |",
         f"| Sanction validity | {k['validity_days']} days (until {valid_until:%d %b %Y}) |", "",
         "## Conditions precedent to disbursement", ""]
    conds = [f"{c.text}" for c in d.conditions]
    conds += ["Legal and technical clearance of the property title, valuation and CERSAI search.",
              "Execution of loan agreement and creation of mortgage in favour of the lender.",
              "Submission of original title documents and own-contribution receipts (if applicable)."]
    for i, c in enumerate(dict.fromkeys(conds), 1):
        lines.append(f"{i}. {c}")
    lines += ["", "## Grievance redressal", "",
          "If you have any concern about this sanction, you may contact our Grievance Redressal Officer "
          "(details on our website and at every branch). If not resolved within 30 days, you may approach "
          "the RBI Ombudsman under the Reserve Bank – Integrated Ombudsman Scheme, 2021 (cms.rbi.org.in).", "",
          f"_Issued under the Fair Practices Code; {policy_ref('RBI_KFS')}._", "",
          "Yours sincerely,", "", "Authorised Signatory — Credit", "", "---", "", DISCLAIMER, ""]
    return "\n".join(lines)


def rejection_letter(case: CaseDetail) -> str:
    d, a = case.decision, case.applicant
    reasons = list(d.reasons)
    if not reasons:
        reasons = [h.detail for h in d.rules_fired if h.effect == "DECLINE"][:5]
    rule_ids = sorted({h.rule_id for h in d.rules_fired if h.effect == "DECLINE"})
    lines = ["# Application Outcome — Letter of Regret (Draft)", "",
         f"**Ref:** {case.id}/RL · **Date:** {datetime.now(timezone.utc):%d %b %Y}", "",
         f"Dear {a.name},", "",
         "Thank you for applying to us. After careful assessment of your application against our credit "
         "policy, we regret that we are **unable to sanction** the loan at this time. In line with the Fair "
         "Practices Code, the main reasons are:", ""]
    lines += [f"{i}. {r}" for i, r in enumerate(reasons, 1)] or ["1. The application does not meet credit policy."]
    if rule_ids:
        lines += ["", f"Policy references: {', '.join(rule_ids)}."]
    lines += ["", "You are welcome to re-apply once the above points are addressed (for example with a co-applicant, "
          "a lower loan amount, or the documents mentioned). This decision does not affect any other "
          "relationship you have with us.", "",
          "## Grievance redressal", "",
          "You may request a review by writing to our Grievance Redressal Officer. If not resolved within 30 "
          "days, you may approach the RBI Ombudsman under the Reserve Bank – Integrated Ombudsman Scheme, 2021.", "",
          f"_{policy_ref('RBI_FPC')}._", "", "Yours sincerely,", "", "Authorised Signatory — Credit", "",
          "---", "", DISCLAIMER, ""]
    return "\n".join(lines)


def referral_note(case: CaseDetail) -> str:
    d = case.decision
    lines = [f"# Case {case.id} — Referred to Underwriter", "",
         "No sanction or rejection letter is issued while the case is under human review.", "",
         "**Reasons for referral**", ""]
    lines += [f"- {r}" for r in d.reasons] or ["- See rules fired in the credit memo."]
    lines += ["", "---", "", DISCLAIMER, ""]
    return "\n".join(lines)


def outcome_letter(case: CaseDetail) -> str:
    """Sanction letter if approved, rejection letter if declined, else a referral note."""
    if case.decision.outcome in APPROVED:
        return sanction_letter(case)
    if case.decision.outcome == DecisionOutcome.DECLINE:
        return rejection_letter(case)
    return referral_note(case)
